def undo_wrong_removals(apps, schema_editor):
    """
    An earlier version of 0009 marked every inactive user sharing an account
    with active ones as removed, and set their password to exactly "!". That
    caught sign-ups from before accounts existed that were still awaiting
    activation. A real removal sets "!" plus random characters, so the marks
    from that version are told apart by the bare "!", and by the user having
    joined before their account was created (0005 made it for existing users).
    """
    User = apps.get_model("app", "CustomUser")
    for user in User.objects.filter(removed_at__isnull=False, is_active=False, password="!").select_related("account"):
        if user.account is not None and user.date_joined <= user.account.created_at:
            User.objects.filter(pk=user.pk).update(removed_at=None)



